customFragmentShaders:
#version 300 es
precision mediump float;

// full-screen UV
in  vec2 vTextureCoord;

// time and resolution from Unicorn Studio
uniform float uTime;
uniform vec2  uResolution;

// output
out vec4 fragColor;

// effect parameters (convert any to uniform if you want runtime control)
const float SPIN_ROTATION = -1.0;
const float SPIN_SPEED    =  0.2;
const vec2  OFFSET        =  vec2(0.0);
const vec4  COLOUR_1      =  vec4(0.871, 0.267, 0.231, 1.0);
const vec4  COLOUR_2      =  vec4(0.0,   0.42,  0.706, 1.0);
const vec4  COLOUR_3      =  vec4(0.086, 0.137, 0.145, 1.0);
const float CONTRAST      =  3.5;
const float LIGHTING      =  0.4;
const float SPIN_AMOUNT   =  0.25;
const float PIXEL_FILTER  = 745.0;
const float SPIN_EASE     =  1.0;
const bool  IS_ROTATE     = false;
const float PI            =  3.14159265359;

// the core “effect” function from Shadertoy
vec4 effect(vec2 screenSize, vec2 screen_coords) {
    // quantize to simulate low-res pixel art
    float pixel_size = length(screenSize) / PIXEL_FILTER;
    vec2 uv = (floor(screen_coords * (1.0 / pixel_size)) * pixel_size
               - 0.5 * screenSize) / length(screenSize)
               - OFFSET;
    float uv_len = length(uv);

    // compute spin speed and angle
    float speed = SPIN_ROTATION * SPIN_EASE * 0.2;
    if (IS_ROTATE) {
        speed = uTime * speed;
    }
    speed += 302.2;
    float angle = atan(uv.y, uv.x)
                + speed
                - SPIN_EASE * 20.0 * (SPIN_AMOUNT * uv_len + (1.0 - SPIN_AMOUNT));
    vec2 mid = (screenSize / length(screenSize)) * 0.5;
    uv = vec2(uv_len * cos(angle) + mid.x,
              uv_len * sin(angle) + mid.y) - mid;

    // scale up for detail
    uv *= 30.0;
    speed = uTime * SPIN_SPEED;
    vec2 uv2 = vec2(uv.x + uv.y);

    // iterate the fractal-like loop
    for (int i = 0; i < 5; i++) {
        uv2 += sin(max(uv.x, uv.y)) + uv;
        uv  += 0.5 * vec2(
                  cos(5.1123314 + 0.353 * uv2.y + speed * 0.131121),
                  sin(uv2.x - 0.113 * speed)
               );
        uv  -= 1.0 * cos(uv.x + uv.y)
             - 1.0 * sin(uv.x * 0.711 - uv.y);
    }

    // paint-style color mixing
    float contrast_mod = (0.25 * CONTRAST + 0.5 * SPIN_AMOUNT + 1.2);
    float paint_res    = min(2.0, max(0.0, length(uv) * 0.035 * contrast_mod));
    float c1p = max(0.0, 1.0 - contrast_mod * abs(1.0 - paint_res));
    float c2p = max(0.0, 1.0 - contrast_mod * abs(paint_res));
    float c3p = 1.0 - min(1.0, c1p + c2p);
    float light = (LIGHTING - 0.2) * max(c1p * 5.0 - 4.0, 0.0)
                + LIGHTING    * max(c2p * 5.0 - 4.0, 0.0);

    // blend final palette
    return (0.3 / CONTRAST) * COLOUR_1
         + (1.0 - 0.3 / CONTRAST) * (
             COLOUR_1 * c1p
           + COLOUR_2 * c2p
           + vec4(COLOUR_3.rgb * c3p, COLOUR_1.a * c3p)
           )
         + light;
}

void main() {
    // reconstruct fragCoord from UV
    vec2 fragCoord = vTextureCoord * uResolution;
    // run the effect
    fragColor = effect(uResolution, fragCoord);
}

customVertexShaders:
#version 300 es
precision mediump float;

in vec3 aVertexPosition;
in vec2 aTextureCoord;

uniform mat4 uMVMatrix;
uniform mat4 uPMatrix;
uniform mat4 uTextureMatrix;

out vec2 vTextureCoord;
out vec3 vVertexPosition;

void main() {
  gl_Position = vec4(aVertexPosition, 1.0);
  vTextureCoord = (vec4(aTextureCoord, 0.0, 1.0)).xy;
}
